const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Asir, Saudi Arabia
  const asirRegion = ee.Geometry.Polygon([
    [42.0, 18.0],
    [44.0, 18.0], 
    [44.0, 20.0],
    [42.0, 20.0],
    [42.0, 18.0]
  ]);

  // 2. Function to get June NDVI for a specific year
  function getJuneNDVI(year) {
    const startDate = ee.Date.fromYMD(year, 5, 1);  // June 1 (month is 0-based)
    const endDate = ee.Date.fromYMD(year, 5, 30);   // June 30

    // Load MODIS MOD13Q1 NDVI collection
    const col = ee.ImageCollection('MODIS/006/MOD13Q1')
      .filterDate(startDate, endDate)
      .filterBounds(asirRegion);

    // Check collection size
    const colSize = col.size();

    // Mask low quality pixels (SummaryQA = 0 means good data)
    const maskedCol = col.map(function(img) {
      const qa = img.select('SummaryQA');
      const mask = qa.eq(0);  // Keep only good quality pixels
      const ndvi = img.select('NDVI')
        .updateMask(mask)
        .multiply(0.0001);  // Scale factor for MOD13Q1 NDVI
      return ndvi.copyProperties(img, ['system:time_start']);
    });

    // Take median of June images
    const medianImg = maskedCol.median();

    return {
      collection: col,
      maskedCollection: maskedCol,
      image: medianImg,
      size: colSize
    };
  }

  // 3. Get long-term NDVI (2003-2011)
  const longTermYears = [];
  const longTermNDVIs = [];

  for (let year = 2003; year <= 2011; year++) {
    const result = getJuneNDVI(year);
    const colSize = result.size.getInfo();

    console.log(`${year} June Images: ${colSize}`);

    if (colSize === 0) {
      console.log(`No images for ${year}, skipping`);
      continue;
    }

    // Compute mean NDVI and pixel count
    const stats = result.image.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: asirRegion,
      scale: 1000,
      maxPixels: 1e9
    });

    const meanNdvi = stats.get('NDVI_mean').getInfo();
    const pixelCount = stats.get('NDVI_count').getInfo();

    console.log(`${year} NDVI: ${meanNdvi ? meanNdvi.toFixed(4) : 'null'}, Valid Pixels: ${pixelCount}`);

    // Check for valid data
    if (pixelCount === 0) {
      console.log(`No valid pixels for ${year}, skipping`);
      continue;
    }

    if (meanNdvi === null || meanNdvi === undefined || isNaN(meanNdvi)) {
      console.log(`Invalid NDVI value for ${year}, skipping`);
      continue;
    }

    // Validate NDVI range
    if (meanNdvi < -1 || meanNdvi > 1) {
      console.log(`NDVI out of range for ${year}: ${meanNdvi}, skipping`);
      continue;
    }

    longTermYears.push(year);
    longTermNDVIs.push(meanNdvi);
  }

  // 4. Check if we have any long-term data
  if (longTermYears.length === 0) {
    console.log("No valid long-term data (2003-2011)");
    console.log("<answer>C1</answer>");
    return;
  }

  // Calculate long-term average
  const longTermAvg = longTermNDVIs.reduce((a, b) => a + b, 0) / longTermNDVIs.length;
  console.log(`Long-term average NDVI (${longTermYears.length} years): ${longTermAvg.toFixed(4)}`);

  // 5. Get 2016 and 2017 NDVI
  const yearsToCheck = [2016, 2017];
  const recentNDVIs = [];

  for (const year of yearsToCheck) {
    const result = getJuneNDVI(year);
    const colSize = result.size.getInfo();

    console.log(`${year} June Images: ${colSize}`);

    if (colSize === 0) {
      console.log(`No images for ${year}`);
      console.log("<answer>C1</answer>");
      return;
    }

    // Compute mean NDVI and pixel count
    const stats = result.image.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: asirRegion,
      scale: 1000,
      maxPixels: 1e9
    });

    const meanNdvi = stats.get('NDVI_mean').getInfo();
    const pixelCount = stats.get('NDVI_count').getInfo();

    console.log(`${year} NDVI: ${meanNdvi ? meanNdvi.toFixed(4) : 'null'}, Valid Pixels: ${pixelCount}`);

    // Check for valid data
    if (pixelCount === 0) {
      console.log(`No valid pixels for ${year}`);
      console.log("<answer>C2</answer>");
      return;
    }

    if (meanNdvi === null || meanNdvi === undefined || isNaN(meanNdvi)) {
      console.log(`Invalid NDVI value for ${year}`);
      console.log("<answer>C3</answer>");
      return;
    }

    // Validate NDVI range
    if (meanNdvi < -1 || meanNdvi > 1) {
      console.log(`NDVI out of range for ${year}: ${meanNdvi}`);
      console.log("<answer>C3</answer>");
      return;
    }

    recentNDVIs.push(meanNdvi);
  }

  // 6. Compare recent years with long-term average
  console.log(`2016 NDVI: ${recentNDVIs[0].toFixed(4)} vs Long-term: ${longTermAvg.toFixed(4)}`);
  console.log(`2017 NDVI: ${recentNDVIs[1].toFixed(4)} vs Long-term: ${longTermAvg.toFixed(4)}`);

  const bothHigher = recentNDVIs[0] > longTermAvg && recentNDVIs[1] > longTermAvg;

  // 7. Output final answer
  if (bothHigher) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
